// Title: How to force hyperlinks to open in a new window when converting Excel to HTML using Aspose.Cells HtmlSaveOptions in C#
// Common Searches: Aspose.Cells C# export Excel to HTML with links opening in a new tab | set target='_blank' for all anchors in HTML generated by Aspose.Cells | C# post‑process Aspose.Cells HTML output to add target attribute to <a> tags | HtmlSaveOptions HtmlLinkTargetType not available, how to add _blank to links | convert workbook to HTML and ensure hyperlinks open in new window using Aspose.Cells .NET
// Tags: Aspose.Cells HtmlSaveOptions target attribute | C# add target='_blank' to generated HTML | Excel workbook to HTML hyperlink new window | post‑process Aspose.Cells HTML output with regex | convert Excel to HTML with Aspose.Cells .NET

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Aspose.Cells;

namespace AsposeCellsHtmlLinkTargetDemo
{
    // The example loads an Excel workbook, saves it as HTML with Aspose.Cells, then uses a C# regular expression to inject target="_blank" into any <a> tags lacking a target attribute, ensuring all hyperlinks open in a new window or tab.
    class Program
    {
        static void Main(string[] args)
        {
            // Define input and output file paths relative to the executable directory
            string inputFile = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "input.xlsx");
            string outputFile = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "output.html");

            // Verify that the input file exists before proceeding
            if (!File.Exists(inputFile))
            {
                Console.Error.WriteLine($"Error: Input file not found at '{inputFile}'. Place an Excel workbook named 'input.xlsx' in the executable directory.");
                return;
            }

            try
            {
                // Load the workbook from the Excel file
                Workbook workbook = new Workbook(inputFile);

                // Configure HTML save options (no direct HtmlLinkTarget property in this version)
                HtmlSaveOptions htmlOptions = new HtmlSaveOptions();

                // Save the workbook as HTML using the configured options
                workbook.Save(outputFile, htmlOptions);

                // Post‑process the generated HTML to ensure all hyperlinks open in a new window/tab
                if (File.Exists(outputFile))
                {
                    string htmlContent = File.ReadAllText(outputFile, Encoding.UTF8);

                    // Add target="_blank" to <a> tags that do not already have a target attribute
                    string processedContent = Regex.Replace(
                        htmlContent,
                        @"<a\s+(?![^>]*\btarget=)",
                        "<a target=\"_blank\" ",
                        RegexOptions.IgnoreCase);

                    File.WriteAllText(outputFile, processedContent, Encoding.UTF8);
                }

                Console.WriteLine($"HTML file successfully saved to '{outputFile}'.");
                Console.WriteLine("All hyperlinks in the generated HTML will open in a new window/tab.");
            }
            catch (Exception ex)
            {
                // Output detailed error information
                Console.Error.WriteLine("An error occurred while converting the workbook to HTML:");
                Console.Error.WriteLine(ex.Message);
                Console.Error.WriteLine(ex.StackTrace);
            }
        }
    }
}
